import React from 'react';
import { Box, Typography, Stack } from '@mui/material';


const ChartTooltip = ({
  
  active,
  payload,
  label,
  
  accentColor,
  prefix = '',
  suffix = '',
  valueFormatter,
  labelKey,
  showAccentBar = true,
  multiSeries = false,
}) => {
  if (!active || !payload || !payload.length) return null;

  const formatDefault = (v) => {
    if (typeof v !== 'number') return String(v ?? '-');
    if (v >= 1_000_000) return `${(v / 1_000_000).toFixed(2)}M`;
    if (v >= 1_000)     return v.toLocaleString('en-US');
    if (v % 1 !== 0)    return v.toFixed(1);
    return v.toString();
  };

  const renderValue = (val) => `${prefix}${valueFormatter ? valueFormatter(val) : formatDefault(val)}${suffix}`;

  const mainLabel = 
    labelKey && payload[0].payload[labelKey] 
      ? payload[0].payload[labelKey] 
      : label || payload[0].payload.name || '';
  const mainAccent = accentColor || payload[0].color || payload[0].stroke || payload[0].fill || '#5BA4F5';

  return (
    <Box
      sx={{
        background: 'linear-gradient(145deg, #1e1e20 0%, #151517 100%)',
        border: `1px solid ${mainAccent}45`,
        borderRadius: '14px',
        px: '16px',
        py: '12px',
        boxShadow: `0 12px 40px rgba(0,0,0,0.65), 0 0 24px ${mainAccent}12`,
        minWidth: '150px',
        pointerEvents: 'none',
      }}
    >
      {mainLabel && (
        <Typography
          sx={{
            fontSize: '0.63rem',
            color: 'rgba(255,255,255,0.38)',
            fontFamily: "'Montserrat', sans-serif",
            fontWeight: 700,
            textTransform: 'uppercase',
            letterSpacing: '0.09em',
            mb: multiSeries ? '8px' : '5px',
          }}
        >
          {mainLabel}
        </Typography>
      )}

      <Stack spacing={multiSeries ? 1.5 : 0}>
        {payload.map((entry, idx) => {
          const entryColor = entry.color || entry.stroke || entry.fill || mainAccent;
          const entryName = entry.name;
          const val = entry.value;

          return (
            <Box key={idx}>
              {multiSeries && entryName && (
                <Stack direction="row" alignItems="center" spacing={1} sx={{ mb: '2px' }}>
                  <Box sx={{ width: 6, height: 6, borderRadius: '50%', bgcolor: entryColor }} />
                  <Typography sx={{ fontSize: '0.65rem', color: 'rgba(255,255,255,0.5)', fontWeight: 600 }}>
                    {entryName}
                  </Typography>
                </Stack>
              )}
              
              <Typography
                sx={{
                  fontSize: multiSeries ? '1rem' : '1.1rem',
                  fontWeight: 800,
                  color: '#fff',
                  fontFamily: "'Montserrat', sans-serif",
                  lineHeight: 1.15,
                }}
              >
                {renderValue(val)}
              </Typography>

              {showAccentBar && !multiSeries && (
                <Box
                  sx={{
                    mt: '8px',
                    height: '2px',
                    borderRadius: '2px',
                    background: `linear-gradient(90deg, ${entryColor}, transparent)`,
                    width: '55%',
                  }}
                />
              )}
            </Box>
          );
        })}
      </Stack>
    </Box>
  );
};

export default ChartTooltip;
