import React, { useState, useEffect, useCallback, useMemo } from "react";
import { Box, Typography, Stack, Tabs, Tab, Chip, FormControl, Select, MenuItem } from "@mui/material";
import MonetizationOnIcon from "@mui/icons-material/MonetizationOn";
import RedeemIcon from "@mui/icons-material/Redeem";
import AccountBalanceWalletIcon from "@mui/icons-material/AccountBalanceWallet";
import PaidIcon from "@mui/icons-material/Paid";
import StatCard from "../../../components/Cards/StatCard";
import AreaGraph from "../../../components/Cards/AreaGraph";
import DataTable from "../../../components/DataTable";
import { useSelector } from "react-redux";
import { toast } from "react-hot-toast";
import dayjs from "dayjs";
import { apiGetJson } from "../../../utils/apiClient";

const Coins = () => {
  const token = useSelector((state) => state.auth.token);

  const [summary, setSummary] = useState(null);
  const [series, setSeries] = useState([]);
  const [chartYear, setChartYear] = useState(new Date().getFullYear());
  const [tab, setTab] = useState(0);

  const [ledger, setLedger] = useState([]);
  const [ledgerLoading, setLedgerLoading] = useState(false);
  const [ledgerPage, setLedgerPage] = useState(0);
  const [ledgerPerPage, setLedgerPerPage] = useState(10);
  const [ledgerTotal, setLedgerTotal] = useState(0);
  const [ledgerSearch, setLedgerSearch] = useState("");
  const [ledgerType, setLedgerType] = useState("all");

  const [redemptions, setRedemptions] = useState([]);
  const [redLoading, setRedLoading] = useState(false);
  const [redPage, setRedPage] = useState(0);
  const [redPerPage, setRedPerPage] = useState(10);
  const [redTotal, setRedTotal] = useState(0);
  const [redSearch, setRedSearch] = useState("");

  const [balances, setBalances] = useState([]);
  const [balLoading, setBalLoading] = useState(false);
  const [balPage, setBalPage] = useState(0);
  const [balPerPage, setBalPerPage] = useState(10);
  const [balTotal, setBalTotal] = useState(0);
  const [balSearch, setBalSearch] = useState("");

  const fetchSummary = useCallback(async () => {
    if (!token) return;
    try {
      const s = await apiGetJson("/admin/coins/summary", token);
      setSummary(s.data || null);
    } catch (err) {
      toast.error(err.message || "Failed to load coins summary");
    }
  }, [token]);

  const fetchSeries = useCallback(async () => {
    if (!token) return;
    try {
      const t = await apiGetJson("/admin/coins/timeseries", token, {
        group: "month",
        start_date: `${chartYear}-01-01`,
        end_date: `${chartYear}-12-31`,
      });
      setSeries(t.data?.series || []);
    } catch (err) {
      console.error("Coins timeseries error:", err);
    }
  }, [token, chartYear]);

  const fetchLedger = useCallback(async () => {
    if (!token) return;
    setLedgerLoading(true);
    try {
      const params = { page: ledgerPage + 1, limit: ledgerPerPage };
      if (ledgerSearch) params.q = ledgerSearch;
      if (ledgerType !== "all") params.type = ledgerType;
      const json = await apiGetJson("/admin/coins/transactions", token, params);
      setLedger(json.data?.transactions || []);
      setLedgerTotal(json.data?.pagination?.total || 0);
    } catch (err) {
      toast.error(err.message || "Failed to load coin ledger");
    } finally {
      setLedgerLoading(false);
    }
  }, [token, ledgerPage, ledgerPerPage, ledgerSearch, ledgerType]);

  const fetchRedemptions = useCallback(async () => {
    if (!token) return;
    setRedLoading(true);
    try {
      const params = { page: redPage + 1, limit: redPerPage };
      if (redSearch) params.q = redSearch;
      const json = await apiGetJson("/admin/coins/redemptions", token, params);
      setRedemptions(json.data?.redemptions || []);
      setRedTotal(json.data?.pagination?.total || 0);
    } catch (err) {
      toast.error(err.message || "Failed to load redemptions");
    } finally {
      setRedLoading(false);
    }
  }, [token, redPage, redPerPage, redSearch]);

  const fetchBalances = useCallback(async () => {
    if (!token) return;
    setBalLoading(true);
    try {
      const params = { page: balPage + 1, limit: balPerPage, sort_by: "balance", sort_order: "desc" };
      if (balSearch) params.q = balSearch;
      const json = await apiGetJson("/admin/coins/balances", token, params);
      setBalances(json.data?.balances || []);
      setBalTotal(json.data?.pagination?.total || 0);
    } catch (err) {
      toast.error(err.message || "Failed to load balances");
    } finally {
      setBalLoading(false);
    }
  }, [token, balPage, balPerPage, balSearch]);

  useEffect(() => { fetchSummary(); }, [fetchSummary]);
  useEffect(() => { fetchSeries(); }, [fetchSeries]);
  useEffect(() => { if (tab === 0) fetchLedger(); }, [tab, fetchLedger]);
  useEffect(() => { if (tab === 1) fetchRedemptions(); }, [tab, fetchRedemptions]);
  useEffect(() => { if (tab === 2) fetchBalances(); }, [tab, fetchBalances]);

  const chartData = useMemo(
    () => (series || []).map((r) => ({ month: r.period_start ? dayjs(r.period_start).format("MMM") : "-", value: r.earned || 0 })),
    [series]
  );

  const ledgerColumns = useMemo(() => [
    { id: "user_name", label: "User", render: (row) => (
        <Box><Typography sx={{ color: "#FFFFFF", fontSize: "0.82rem", fontWeight: 500 }}>{row.user_name}</Typography><Typography sx={{ color: "#8B8D97", fontSize: "0.7rem" }}>{row.user_email}</Typography></Box>
      ) },
    { id: "type", label: "Type", render: (row) => (
        <Chip label={row.type} size="small" sx={{ bgcolor: row.type === "earned" ? "rgba(76,198,110,0.15)" : "rgba(255,80,80,0.15)", color: row.type === "earned" ? "#4CC66E" : "#FF5050", fontWeight: 700, fontSize: "0.7rem", borderRadius: "6px", textTransform: "capitalize" }} />
      ) },
    { id: "points_amount", label: "Coins", align: "right", render: (row) => (
        <Typography sx={{ color: row.type === "earned" ? "#4CC66E" : "#FF5050", fontSize: "0.85rem", fontWeight: 700 }}>{row.type === "earned" ? "+" : "-"}{row.points_amount}</Typography>
      ) },
    { id: "module_type", label: "Module", render: (row) => (
        <Typography sx={{ color: "#8B8D97", fontSize: "0.8rem", textTransform: "capitalize" }}>{row.module_type}</Typography>
      ) },
    { id: "created_at", label: "Date", render: (row) => (
        <Typography sx={{ color: "#8B8D97", fontSize: "0.8rem", whiteSpace: "nowrap" }}>{row.created_at ? dayjs(row.created_at).format("DD MMM YYYY") : "-"}</Typography>
      ) },
  ], []);

  const redemptionColumns = useMemo(() => [
    { id: "user_name", label: "User", render: (row) => (
        <Box><Typography sx={{ color: "#FFFFFF", fontSize: "0.82rem", fontWeight: 500 }}>{row.user_name}</Typography><Typography sx={{ color: "#8B8D97", fontSize: "0.7rem" }}>{row.user_email}</Typography></Box>
      ) },
    { id: "redeem_code", label: "Code", render: (row) => (
        <Chip label={row.redeem_code} size="small" sx={{ bgcolor: "rgba(159,110,218,0.15)", color: "#9F6EDA", fontWeight: 700, fontSize: "0.7rem", borderRadius: "6px" }} />
      ) },
    { id: "rule_name", label: "Reward", render: (row) => (
        <Typography sx={{ color: "#FFFFFF", fontSize: "0.82rem" }}>{row.rule_name}</Typography>
      ) },
    { id: "points_amount", label: "Coins", align: "right", render: (row) => (
        <Typography sx={{ color: "#F5A623", fontSize: "0.85rem", fontWeight: 700 }}>{row.points_amount}</Typography>
      ) },
    { id: "created_at", label: "Date", render: (row) => (
        <Typography sx={{ color: "#8B8D97", fontSize: "0.8rem", whiteSpace: "nowrap" }}>{row.created_at ? dayjs(row.created_at).format("DD MMM YYYY") : "-"}</Typography>
      ) },
  ], []);

  const balanceColumns = useMemo(() => [
    { id: "user_name", label: "User", render: (row) => (
        <Box><Typography sx={{ color: "#FFFFFF", fontSize: "0.82rem", fontWeight: 500 }}>{row.user_name}</Typography><Typography sx={{ color: "#8B8D97", fontSize: "0.7rem" }}>{row.user_email}</Typography></Box>
      ) },
    { id: "earned", label: "Earned", align: "right", render: (row) => (
        <Typography sx={{ color: "#4CC66E", fontSize: "0.85rem", fontWeight: 600 }}>{row.earned}</Typography>
      ) },
    { id: "redeemed", label: "Redeemed", align: "right", render: (row) => (
        <Typography sx={{ color: "#FF5050", fontSize: "0.85rem", fontWeight: 600 }}>{row.redeemed}</Typography>
      ) },
    { id: "balance", label: "Balance", align: "right", render: (row) => (
        <Typography sx={{ color: "#FFFFFF", fontSize: "0.9rem", fontWeight: 800 }}>{row.balance}</Typography>
      ) },
  ], []);

  const typeFilter = (
    <FormControl size="small" sx={{ minWidth: 120 }}>
      <Select value={ledgerType} onChange={(e) => { setLedgerType(e.target.value); setLedgerPage(0); }}
        sx={{ height: 36, bgcolor: "rgba(255,255,255,0.05)", borderRadius: "8px", color: "rgba(255,255,255,0.85)", fontSize: "0.75rem", fontWeight: 600, "& .MuiOutlinedInput-notchedOutline": { borderColor: "rgba(255,255,255,0.12)" }, "& .MuiSvgIcon-root": { color: "rgba(255,255,255,0.5)" } }}
        MenuProps={{ PaperProps: { sx: { bgcolor: "#001e08ff", border: "1px solid rgba(255,255,255,0.1)", "& .MuiMenuItem-root": { fontSize: "0.78rem", color: "#fff" } } } }}>
        <MenuItem value="all">All Types</MenuItem>
        <MenuItem value="earned">Earned</MenuItem>
        <MenuItem value="redeemed">Redeemed</MenuItem>
      </Select>
    </FormControl>
  );

  return (
    <Box sx={{ p: { xs: 2, md: 4 }, minHeight: "100vh", background: "linear-gradient(135deg, #0F0F10 0%, #1A1A1C 100%)" }}>
      <Stack sx={{ mb: 4 }}>
        <Typography variant="h4" sx={{ fontWeight: 800, color: "#fff", fontFamily: "'Montserrat', sans-serif", letterSpacing: "-0.04em", mb: 1 }}>
          Coins Economy
        </Typography>
        <Typography variant="body2" sx={{ color: "rgba(255,255,255,0.4)", fontWeight: 500, fontFamily: "'Montserrat', sans-serif" }}>
          Coins earned, redeemed, outstanding balances and top users.
        </Typography>
      </Stack>

      <Box sx={{ display: "flex", flexDirection: { xs: "column", sm: "row" }, gap: { xs: 1.5, md: 3 }, mb: 3 }}>
        <StatCard title="Total Earned" value={summary?.total_earned || 0} icon={<MonetizationOnIcon />} iconColor="#4CC66E" />
        <StatCard title="Total Redeemed" value={summary?.total_redeemed || 0} icon={<RedeemIcon />} iconColor="#FF5050" />
        <StatCard title="Outstanding Balance" value={summary?.outstanding_balance || 0} icon={<AccountBalanceWalletIcon />} iconColor="#9F6EDA" />
        <StatCard title="Redemptions" value={summary?.redeem_events || 0} icon={<PaidIcon />} iconColor="#F5A623" subtitle={`${summary?.active_users || 0} active users`} />
      </Box>

      <Box sx={{ mb: 3 }}>
        <AreaGraph title="Coins Earned Over Time" data={chartData} lineColor="#F5A623" selectedYear={chartYear} onYearChange={(yr) => setChartYear(yr)} />
      </Box>

      <Tabs value={tab} onChange={(_, v) => setTab(v)}
        sx={{ mb: 2, "& .MuiTab-root": { color: "rgba(255,255,255,0.5)", textTransform: "none", fontWeight: 600, fontFamily: "'Montserrat', sans-serif" }, "& .Mui-selected": { color: "#4CC66E !important" }, "& .MuiTabs-indicator": { backgroundColor: "#4CC66E" } }}>
        <Tab label="Ledger" />
        <Tab label="Redemptions" />
        <Tab label="Balances" />
      </Tabs>

      {tab === 0 && (
        <DataTable title="Coin Ledger" columns={ledgerColumns} data={ledger} isLoading={ledgerLoading}
          searchTerm={ledgerSearch} onSearchChange={(val) => { setLedgerSearch(val); setLedgerPage(0); }} filters={typeFilter}
          pagination={{ page: ledgerPage, rowsPerPage: ledgerPerPage, totalCount: ledgerTotal, onPageChange: (_, p) => setLedgerPage(p), onRowsPerPageChange: (e) => { setLedgerPerPage(parseInt(e.target.value, 10)); setLedgerPage(0); } }}
          emptyTitle="No coin activity" emptyMessage="No earned/redeemed coin events match your filters." />
      )}

      {tab === 1 && (
        <DataTable title="Redemptions" columns={redemptionColumns} data={redemptions} isLoading={redLoading}
          searchTerm={redSearch} onSearchChange={(val) => { setRedSearch(val); setRedPage(0); }}
          pagination={{ page: redPage, rowsPerPage: redPerPage, totalCount: redTotal, onPageChange: (_, p) => setRedPage(p), onRowsPerPageChange: (e) => { setRedPerPage(parseInt(e.target.value, 10)); setRedPage(0); } }}
          emptyTitle="No redemptions" emptyMessage="No coin redemptions recorded yet." />
      )}

      {tab === 2 && (
        <DataTable title="User Balances" columns={balanceColumns} data={balances} isLoading={balLoading}
          searchTerm={balSearch} onSearchChange={(val) => { setBalSearch(val); setBalPage(0); }}
          pagination={{ page: balPage, rowsPerPage: balPerPage, totalCount: balTotal, onPageChange: (_, p) => setBalPage(p), onRowsPerPageChange: (e) => { setBalPerPage(parseInt(e.target.value, 10)); setBalPage(0); } }}
          emptyTitle="No balances" emptyMessage="No users with coin activity yet." />
      )}
    </Box>
  );
};

export default Coins;
